#include <BleKeyboard.h>

BleKeyboard bleKeyboard("ESP32 Music Controller", "ESP32", 100);

#define TOUCH_PIN 4

bool lastState = LOW;
unsigned long touchStart = 0;

void setup() {
  Serial.begin(115200);

  pinMode(TOUCH_PIN, INPUT);

  bleKeyboard.begin();

  Serial.println("ESP32 Music Controller Started");
  Serial.println("Connect 'ESP32 Music Controller' from your phone Bluetooth.");
}

void loop() {

  bool currentState = digitalRead(TOUCH_PIN);

  // Touch started
  if (currentState == HIGH && lastState == LOW) {
    touchStart = millis();
  }

  // Touch released
  if (currentState == LOW && lastState == HIGH) {

    unsigned long touchTime = millis() - touchStart;

    if (bleKeyboard.isConnected()) {

      if (touchTime < 1000) {
        // Short touch = Play/Pause
        bleKeyboard.write(KEY_MEDIA_PLAY_PAUSE);
        Serial.println("Play / Pause");
      }
      else {
        // Long touch = Next Song
        bleKeyboard.write(KEY_MEDIA_NEXT_TRACK);
        Serial.println("Next Song");
      }
    }
    else {
      Serial.println("Bluetooth not connected!");
    }
  }

  lastState = currentState;

  delay(20);
}
